import re

def parse(lines):
    blocks = []
    skip = []
    kv = None
    tbl = None
    vlan = None
    sect = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if re.search(r'#\s*show\b', l) or re.match(r'^-+(\s+-+)*$', s):
            skip.append(i)
            continue
        m = re.match(r'^(VLAN\d+|MST\d+)$', s)
        if m:
            vlan = m.group(1)
            kv = {'name': 'spanning_tree', 'kind': 'kv', 'lines': [i], 'records': [{'VLAN': vlan}]}
            blocks.append(kv)
            tbl = None
            sect = None
            continue
        if re.match(r'^Interface\s+Role\s+Sts', s):
            tbl = {'name': 'interfaces', 'kind': 'table', 'lines': [i], 'records': []}
            blocks.append(tbl)
            sect = None
            continue
        if tbl is not None:
            m = re.match(r'^(?P<i>\S+)\s+(?P<r>\S+)\s+(?P<s>\S+)\s+(?P<c>\d+)\s+(?P<p>[\d.]+)(?:\s+(?P<t>\S.*?))?\s*$', l)
            if m:
                tbl['lines'].append(i)
                tbl['records'].append({'VLAN': vlan or '', 'Interface': m.group('i'), 'Role': m.group('r'), 'Sts': m.group('s'), 'Cost': m.group('c'), 'Prio.Nbr': m.group('p'), 'Type': m.group('t') or ''})
                continue
        if kv is None:
            kv = {'name': 'spanning_tree', 'kind': 'kv', 'lines': [], 'records': [{}]}
            blocks.append(kv)
        rec = kv['records'][0]
        m = re.match(r'^\s*Spanning tree enabled protocol\s+(\S+)', l)
        if m:
            rec['Protocol'] = m.group(1)
            kv['lines'].append(i)
            continue
        m = re.match(r'^\s{0,3}(Root ID|Bridge ID)\s+(.*)$', l)
        rest = None
        if m:
            sect = m.group(1)
            rest = m.group(2).strip()
        elif l.startswith(' ') and sect:
            rest = s
        if rest is None:
            continue
        used = False
        if re.search(r'\d+ sec\b', rest):
            for k, v in re.findall(r'([A-Za-z][A-Za-z ]*?)\s+(\d+ sec)', rest):
                rec[sect + ' ' + k.strip()] = v
                used = True
        else:
            m2 = re.match(r'^(\S+(?: \S+)*?)\s{2,}(\S.*)$', rest)
            if m2:
                k = m2.group(1)
                v = m2.group(2).strip()
                mm = re.match(r'^(\d+)\s+\(priority (\d+) sys-id-ext (\d+)\)', v)
                if mm:
                    rec[sect + ' ' + k] = mm.group(1)
                    rec[sect + ' priority'] = mm.group(2)
                    rec[sect + ' sys-id-ext'] = mm.group(3)
                else:
                    rec[sect + ' ' + k] = v
                used = True
            elif re.search(r'This bridge is the root', rest):
                rec[sect + ' This bridge is the root'] = 'yes'
                used = True
        if used:
            kv['lines'].append(i)
    return {'blocks': blocks, 'skip': skip}
